css:
.editor {
  max-inline-size: 40rem;
  border: 1px solid var(--va-color-border, currentColor);
  border-radius: var(--va-radius-md, 0.5rem);
  overflow: hidden;
}

.format-toolbar {
  display: flex;
  gap: var(--va-space-1, 0.25rem);
  padding: var(--va-space-2, 0.5rem);
  border-block-end: 1px solid var(--va-color-border, currentColor);
}

.format-toolbar svg {
  display: block;
  inline-size: 1.25rem;
  block-size: 1.25rem;
}

.editor-content {
  min-block-size: 8rem;
  padding: var(--va-space-3, 0.75rem) var(--va-space-4, 1rem);
}

.editor-content:focus-visible {
  outline: 2px solid var(--va-color-focus, Highlight);
  outline-offset: -2px;
}

js:
const editor = document.getElementById('editor');
const toolbar = document.querySelector('.format-toolbar');
let savedRange = null;

// Remember the last selection inside the editor, so it survives focus
// moving to a toolbar button (by mouse or keyboard).
document.addEventListener('selectionchange', () => {
  const selection = document.getSelection();
  if (selection && selection.rangeCount > 0) {
    const range = selection.getRangeAt(0);
    if (editor.contains(range.commonAncestorContainer)) {
      savedRange = range.cloneRange();
    }
  }
});

toolbar.addEventListener('click', (event) => {
  const button = event.target.closest('va-button[data-command]');
  if (!button) return;

  editor.focus();
  if (savedRange) {
    const selection = document.getSelection();
    selection.removeAllRanges();
    selection.addRange(savedRange);
  }
  document.execCommand(button.dataset.command, false);
});
